// GuidePoint Named Accounts - June 2026
// 1234 blocked + 595 open (Pete Ballas + Carl Morris)
// New accounts not on any list are treated as Available by default

export const OPEN_OWNERS = ['Pete Ballas', 'Carl Morris']

const sim = (s1, s2) => {
  if (!s1 || !s2) return 0
  s1 = s1.toLowerCase().trim(); s2 = s2.toLowerCase().trim()
  if (s1 === s2) return 1
  if (s1.length < 2 || s2.length < 2) return 0
  const bg = new Set()
  for (let i = 0; i < s1.length - 1; i++) bg.add(s1.slice(i,i+2))
  let m = 0
  for (let i = 0; i < s2.length - 1; i++) { if (bg.has(s2.slice(i,i+2))) m++ }
  return (2*m)/(s1.length+s2.length-2)
}

// Returns true only if account is named by someone OTHER than Pete/Carl
export const isBlockedAccount = (n) => {
  if (!n) return false
  const name = n.toLowerCase().trim()
  return NAMED_ACCOUNTS_BLOCKED.some(a => {
    const an = a.n.toLowerCase().trim()
    return an === name || an.includes(name) || name.includes(an) || sim(an,name) > 0.82
  })
}

// Returns the owner name if found in either list, null if brand new unknown account
export const getAccountOwner = (n) => {
  if (!n) return null
  const name = n.toLowerCase().trim()
  const all = [...NAMED_ACCOUNTS_BLOCKED, ...NAMED_ACCOUNTS_OPEN]
  const match = all.find(a => { 
    const an = a.n.toLowerCase().trim()
    return an===name||an.includes(name)||name.includes(an)||sim(an,name)>0.85 
  })
  return match ? match.o : null
}

// Returns true if account is Pete/Carl open placeholder
export const isOpenNamedAccount = (n) => {
  if (!n) return false
  const name = n.toLowerCase().trim()
  return NAMED_ACCOUNTS_OPEN.some(a => { 
    const an = a.n.toLowerCase().trim()
    return an===name||an.includes(name)||name.includes(an)||sim(an,name)>0.82 
  })
}

